A small Java Test app

```java
import java.lang.management.ManagementFactory;
import java.lang.management.OperatingSystemMXBean;
import java.lang.reflect.Method;
import org.opensearch.monitor.os.OsProbe;

public class DiagnosticCpuLoadSampler {
    public static void main(String[] args) throws Exception {
        // Use the same OpenSearch-based Adaptive Probe
        OsProbe osProbe = OsProbe.getInstance();

        int samples = 6;
        double min = Double.POSITIVE_INFINITY;
        double max = Double.NEGATIVE_INFINITY;
        double sum = 0.0;

        for (int i = 1; i <= samples; i++) {
            short cpuPercent = osProbe.getSystemCpuPercent();
            double value = cpuPercent < 0 ? 0.0 : cpuPercent / 100.0; // 0.0 - 1.0
            System.out.printf("cpu: %d %n", cpuPercent);

            System.out.printf("sample %d: %.4f%n", i, value);

            if (value < min) min = value;
            if (value > max) max = value;
            sum += value;

            try { Thread.sleep(10000); } catch (InterruptedException ignore) {}
        }

        double avg = sum / Math.max(1, samples);
        System.out.printf("Summary: samples=%d, min=%.4f, max=%.4f, avg=%.4f%n",
                samples, min, max, avg);
        System.out.printf("Summary (percent): min=%.2f%%, max=%.2f%%, avg=%.2f%%%n",
                min * 100, max * 100, avg * 100);
    }
}
```

